]

output = [
    [0, 0, 8],
    [8, 8, 0],
    [0, 8, 0]
]

# What if we're looking for regions where ALL non-zero cells are connected 
# through adjacent (horizontal/vertical) paths of same value?

def find_connected_components_of_ones(input_grid, ro_start, co_start):
    rows_in, cols_in = len(input_grid), len(input_grid[0])

    # Map relative coordinates to absolute
    r_map = lambda i: min(i + ro_start * (rows_in // 3), rows_in)
    c_map = lambda j: min(j + co_start * (cols_in // 3), cols_in)

    ones = []
    for r in range(ro_start, min(ro_start + rows_in // 3 + 1, rows_in)):
        for c in range(co_start, min(co_start + cols_in // 3 + 1, cols_in)):
            if input_grid[r][c] == 1:
                ones.append((r,c))

    if not ones:
        return {"count": 0, "connected": True}

    visited = set()
    comp_count = 0

    def dfs(cell):
        stack = [cell]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr[0]+dr, curr[1]+dc
                if 0 <= nr < rows_in and 0 <= nc < cols_in and \
                   input_grid[nr][nc] == 1 and (nr, nc) not in visited:
                    stack.append((nr, nc))

    for cell in ones:
        if cell not in visited:
            dfs(cell)
            comp_count += 1

    return {"count": len(ones), "connected": comp_count == 1, "components": comp_count}

print("\nComponent analysis:")
for ro in range(3):
    for co in range(3):
        r_start = ro * 2  # 7 rows / 3 ≈ 2.33, use 2
        c_start = co * 2  # 7 cols / 3 ≈ 2.33, use 2
        result = find_connected_components_of_ones(demo_input, r_start, c_start)
        print(f"[{ro},{co}]: {result}")

